def page(title, body, script=''):
    return '<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'+h(title)+'</title><link rel="stylesheet" href="review.css"></head><body><main>'+NAV+body+'<p class="foot">Week 7 · prepared 15 October 2026 · local instructor review · current slide numbers refer to v15; lettered IDs are proposed insertions.</p></main>'+script+'</body></html>'
def write(name,title,body,script=''):
    (OUT/name).write_text(page(title,body,script),encoding='utf-8')
def fig(src,caption):
    return f'<figure><a href="{h(src)}"><img class="wide-image" loading="lazy" src="{h(src)}" alt="{h(caption)}"></a><figcaption>{h(caption)}</figcaption></figure>'
def links(keys):
    return ' · '.join(f'<a href="{h(SOURCES[k][1])}">{h(SOURCES[k][0])}</a>' for k in keys)

def visible_detail(p):
    d=p.get('visible_detail')
    if not d:return ''
    result='<div class="teaching-detail"><h4>'+h(d['label'])+'</h4>'
    if d['type']=='table':
        result+='<table><thead><tr>'+''.join('<th>'+h(c)+'</th>' for c in d['columns'])+'</tr></thead><tbody>'
        result+=''.join('<tr>'+''.join('<td>'+h(c)+'</td>' for c in row)+'</tr>' for row in d['rows'])+'</tbody></table>'
    elif d['type']=='code':result+='<pre><code>'+h(d['text'])+'</code></pre>'
    else:result+='<blockquote>'+h(d['text'])+'</blockquote>'
    if d.get('context'):result+='<p class="meta">'+h(d['context'])+'</p>'
    return result+'</div>'

